cd /tmp && node -e '
const {spawnSync}=require("child_process");
const EXE="/workspace/dataset/test5_executable";
function run(a,b,label){const r=spawnSync(EXE,["--a",a,"--b",b],{encoding:"utf8"});const e=(r.stderr||"").split("\n").filter(l=>/^[A-Za-z_.]*(Error|Exception)/.test(l)).pop()||"";console.log(label.padEnd(46),"code="+r.status,"out="+JSON.stringify(r.stdout||""),e.slice(0,80));}
// deep nested properties schema, instance matching depth
for(const d of [10,50,100,200,300,400,500,1000]){
  let s={type:"integer"}; let i=1;
  for(let k=0;k<d;k++){ s={properties:{a:s}}; i={a:i}; }
  run(JSON.stringify(i),JSON.stringify(s),`deep properties d=${d}`);
}
// self ref with deep instance
for(const d of [5,20,50,100,200,300,500]){
  let i=1; for(let k=0;k<d;k++) i={a:i};
  run(JSON.stringify(i),JSON.stringify({properties:{a:{"$ref":"#"}}}),`selfref instance depth=${d}`);
}
// deep array items
for(const d of [100,300,600]){
  let s={type:"integer"}; let i=1;
  for(let k=0;k<d;k++){ s={items:s}; i=[i]; }
  run(JSON.stringify(i),JSON.stringify(s),`deep items d=${d}`);
}
// allOf self ref
run("1",JSON.stringify({allOf:[{"$ref":"#"}]}),"allOf selfref");
run("1",JSON.stringify({not:{"$ref":"#"}}),"not selfref");
run("1",JSON.stringify({anyOf:[{},{"$ref":"#"}]}),"anyOf [{} , selfref]");
run("1",JSON.stringify({anyOf:[{"$ref":"#"},{}]}),"anyOf [selfref, {}]");
run("1",JSON.stringify({definitions:{a:{"$ref":"#/definitions/a"}}}),"unused recursive def");
run("1",JSON.stringify({"$ref":"#/definitions/a",definitions:{a:{allOf:[{"$ref":"#/definitions/a"}]}}}),"mutual allOf ref");
// deep allOf chain (no ref)
for(const d of [100,300,600,1000]){ let s={type:"integer"}; for(let k=0;k<d;k++) s={allOf:[s]}; run("\"x\"",JSON.stringify(s),`deep allOf d=${d}`); }
'

cd /tmp && node -e '
const {spawnSync}=require("child_process");
const EXE="/workspace/dataset/test5_executable";
function ok(d){ let s={type:"integer"}; let i=1; for(let k=0;k<d;k++){ s={properties:{a:s}}; i={a:i}; } const r=spawnSync(EXE,["--a",JSON.stringify(i),"--b",JSON.stringify(s)],{encoding:"utf8"}); return r.status===0; }
let lo=400,hi=500; while(hi-lo>1){const m=(lo+hi)>>1; if(ok(m)) lo=m; else hi=m;} console.log("deep properties: max ok depth =",lo,"first fail =",hi);
function ok2(d){ let s={type:"integer"}; for(let k=0;k<d;k++) s={allOf:[s]}; const r=spawnSync(EXE,["--a","\"x\"","--b",JSON.stringify(s)],{encoding:"utf8"}); return r.status===0; }
lo=300;hi=600; while(hi-lo>1){const m=(lo+hi)>>1; if(ok2(m)) lo=m; else hi=m;} console.log("deep allOf: max ok =",lo,"first fail =",hi);
